{"query":"query ReadProductVariantPage($productId: ID!, $after: String) {
  product(id: $productId) {
    id
    variants(first: 2, after: $after) {
      nodes {
        id
        sku
        price
        selectedOptions { name value }
        inventoryQuantity
        inventoryItem { id tracked }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
}"}
